<form><input class="input" name="ip" placeholder="IP" value="<?= e($_GET['ip']??'') ?>"> <input class="input" name="uri" placeholder="<?= e(t('URI contains')) ?>" value="<?= e($_GET['uri']??'') ?>"> <input class="input" name="site" placeholder="<?= e(t('Site')) ?>" value="<?= e($_GET['site']??'') ?>"> <select class="input" name="risk"><option value=""><?= e(t('Any risk')) ?></option><?php foreach(['low','medium','high','critical'] as $r): ?><option value="<?= e($r) ?>" <?= ($_GET['risk']??'')===$r?'selected':'' ?>><?= e(t($r)) ?></option><?php endforeach ?></select> <input class="input" name="type" placeholder="<?= e(t('Type')) ?>" value="<?= e($_GET['type']??'') ?>"> <input class="input" type="date" name="date_from" value="<?= e($_GET['date_from']??'') ?>"> <input class="input" type="date" name="date_to" value="<?= e($_GET['date_to']??'') ?>"> <button class="btn"><?= e(t('Filter')) ?></button> <a class="btn" href="/logs/export.csv?<?= e(http_build_query($_GET)) ?>"><?= e(t('Export CSV')) ?></a></form>
